<script setup lang="ts">import{onMounted,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const values=ref<components['schemas']['GuardEvent'][]>([]);const error=ref('');onMounted(async()=>{try{values.value=requireData(await client.GET('/api/admin/guard/events'))}catch(cause){error.value=errorMessage(cause)}})</script>
<template><PageHeader title="问答防滥用" description="展示程序检查、模型风险和预算触发的事件；不包含提问正文或原始 IP。"/><p v-if="error" class="text-danger">{{ error }}</p><table class="w-full"><thead><tr><th>时间</th><th>风险</th><th>原因</th><th>范围</th></tr></thead><tbody><tr v-for="value in values" :key="`${value.created}:${value.scope}`"><td>{{ value.created }}</td><td>{{ value.risk }}</td><td>{{ value.reason }}</td><td>{{ value.scope }}</td></tr></tbody></table></template>
